package com.gamehubstore.notification_mscv.services; import com.gamehubstore.notification_mscv.models.Notification; import com.gamehubstore.notification_mscv.repositories.NotificationRepository; import com.gamehubstore.notification_mscv.client.UserClient; import org.slf4j.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class NotificationService { private static final Logger log=LoggerFactory.getLogger(NotificationService.class); private final NotificationRepository repo; private final UserClient users; public NotificationService(NotificationRepository r,UserClient u){repo=r;users=u;} public List<Notification> all(){return repo.findAll();} public List<Notification> byUser(Long id){return repo.findByUserIdAndArchivedFalse(id);} public Notification byId(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Notificación no encontrada: "+id));}
 @Transactional public Notification create(Notification n){users.findUser(n.getUserId()); n.setRead(false);n.setArchived(false); log.info("Creando notificación usuario={} tipo={}",n.getUserId(),n.getType()); return repo.save(n);} @Transactional public Notification markRead(Long id){Notification n=byId(id);if(!n.isRead()){n.setRead(true);return repo.save(n);}return n;} @Transactional public void archive(Long id){Notification n=byId(id);n.setArchived(true);repo.save(n);}
}
